    title: document.title,
    width: de.clientWidth,
    height: Math.max(de.scrollHeight, document.body ? document.body.scrollHeight : 0),
    texts: ctx.texts.length,
    elements: ctx.elements.length,
    ms: Math.round(performance.now() - t0),
