    darkModeCss: RL.hasDarkModeCss(),
    links: Array.from(document.querySelectorAll('a[href]')).map((a) => a.href).filter((h) => /^https?:/.test(h)).slice(0, 500),
    suppressed: document.querySelectorAll('[data-renderlint-ignore]').length,
